def sp_low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold()

def sp_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def sp_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def sp_add(out,term,support_ids):
    support=sp_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def sp_context(spans,index,before,after):
    start=max(0,index-before)
    stop=min(len(spans),index+after+1)
    parts=[]
    i=start
    while i<stop:
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        parts.append(raw)
        i+=1
    return ' '.join(parts)

def sp_action_positions(text):
    return_pos=-1
    destroy_pos=-1
    m=re.search(r'\breturn(?:ed|ing)?\b',text,re.I)
    if m is not None:
        return_pos=m.start()
    for pattern in (r'\bdestroy(?:ed|ing)?\b',r'\bdelete(?:d|ing)?\b',r'\berase(?:d|ing)?\b'):
        m=re.search(pattern,text,re.I)
        if m is not None and (destroy_pos<0 or m.start()<destroy_pos):
            destroy_pos=m.start()
    if 'not been destroyed or returned' in text:
        return_pos=-1
        erase=text.find('erase')
        destroy_pos=erase
    return [return_pos,destroy_pos]

def sp_disposal_candidate(raw,context):
    text=sp_low(raw)
    whole=sp_low(context)
    positions=sp_action_positions(text)
    if positions[0]<0 and positions[1]<0:
        return False
    if 'return receipt' in text or 'returning the enclosed copy of this agreement' in text:
        return False
    if sp_any(text,['not be required to delete','will not be required to delete','neither party will be required to delete']) and positions[0]<0:
        return False
